const incoming = $input.first().json || {};
const centralConfig = incoming.centralConfig || {};
const globalConfig = centralConfig.globalConfig || {};
const channelConfig = (centralConfig.channels || {}).localStackAi || {};
const bindings = centralConfig.workflowBindings || {};
const cfg = { ...globalConfig, ...channelConfig, ...incoming };
const requestedRunType = String(cfg.requestedRunType || cfg.runType || 'CONTENT_DAILY').toUpperCase();
const isUnset = (value) => {
  if (value === undefined || value === null) return true;
  const text = String(value).trim();
  if (!text) return true;
  const upper = text.toUpperCase();
  return upper.includes('PASTE_') || upper.includes('REPLACE_WITH_') || upper.includes('YOUR_') || upper.startsWith('DEMO-') || text.includes('example.com');
};
const requiredFields = ['groqApiKey', 'flikiApiKey', 'googleSheetId', 'uploadPostApiKey', 'slackWebhook', 'youtubeChannelId', 'youtubeChannelUrl', 'mainSiteUrl', 'mainOfferUrl'];
const missingFieldNames = requiredFields.filter(key => isUnset(cfg[key]));
const sharedContentWorkflowId = cfg.sharedContentWorkflowId || bindings.sharedContentWorkflowId || 'ZHXBmDQ7mhI8lEoH';
const sharedAnalyticsWorkflowId = cfg.sharedAnalyticsWorkflowId || bindings.sharedAnalyticsWorkflowId || '7MbU3Q9mCewtH7xw';
const sharedStrategyWorkflowId = cfg.sharedStrategyWorkflowId || bindings.sharedStrategyWorkflowId || 'pMFr3Sgak21AIOPx';
const missingBindings = [['sharedContentWorkflowId', sharedContentWorkflowId], ['sharedAnalyticsWorkflowId', sharedAnalyticsWorkflowId], ['sharedStrategyWorkflowId', sharedStrategyWorkflowId]].filter(([, v]) => isUnset(v)).map(([k]) => k);
const setupReady = missingFieldNames.length === 0 && missingBindings.length === 0;
const policyBlocked = cfg.maintenanceMode === true || cfg.enabled === false || cfg.channelEnabled === false;
const testModeBlocked = String(cfg.globalMode || 'LIVE').toUpperCase() === 'TEST' && !cfg.allowContentInTestMode;
const lockWindowMinutes = Number(cfg.runLockWindowMinutes || 90);
const minuteBucket = Math.floor(Date.now() / (Math.max(lockWindowMinutes, 1) * 60 * 1000));
const runLockKey = ['localStackAi', requestedRunType, minuteBucket].join(':');
let status = 'READY_TO_ROUTE';
let targetWorkflowId = '';
let reason = '';
if (requestedRunType === 'SETUP_AUDIT') {
  status = 'SETUP_AUDIT_COMPLETE';
  reason = setupReady ? 'Setup ready' : 'Setup missing fields or bindings';
} else if (!setupReady) {
  status = 'WRAPPER_BLOCKED';
  reason = 'Missing required setup fields or bindings: ' + missingFieldNames.join(', ');
} else if (policyBlocked) {
  status = 'WRAPPER_BLOCKED';
  reason = 'Blocked by maintenance/channel policy';
} else if (testModeBlocked) {
  status = 'WRAPPER_BLOCKED';
  reason = 'Blocked because globalMode=TEST and allowContentInTestMode=false';
} else if (['CONTENT_DAILY', 'DRAFT_MINING', 'CONTENT_SHORTS'].includes(requestedRunType)) {
  if (cfg.allowContent === false) { status = 'WRAPPER_BLOCKED'; reason = 'Content runs disabled for channel'; }
  else if (requestedRunType === 'CONTENT_SHORTS' && cfg.shortsEnabled === false) { status = 'WRAPPER_BLOCKED'; reason = 'Shorts disabled for this channel'; }
  else { targetWorkflowId = sharedContentWorkflowId; }
} else if (requestedRunType.startsWith('ANALYTICS_')) {
  if (cfg.allowAnalytics === false || cfg.analyticsEnabled === false) { status = 'WRAPPER_BLOCKED'; reason = 'Analytics runs disabled for channel'; }
  else { targetWorkflowId = sharedAnalyticsWorkflowId; }
} else if (['WEEKLY_STRATEGY', 'MILESTONE_CHECK'].includes(requestedRunType)) {
  if (cfg.allowStrategy === false || cfg.strategyEnabled === false) { status = 'WRAPPER_BLOCKED'; reason = 'Strategy runs disabled for channel'; }
  else { targetWorkflowId = sharedStrategyWorkflowId; }
} else {
  status = 'SKIPPED_UNSUPPORTED_RUN';
  reason = 'Unsupported run type in wrapper: ' + requestedRunType;
}
const deadLetter = (status === 'WRAPPER_BLOCKED' || status === 'SKIPPED_UNSUPPORTED_RUN') ? { channelKey: 'localStackAi', channelName: cfg.channelName || 'Local Stack AI', runType: requestedRunType, reason, missingFieldNames, missingBindings, at: new Date().toISOString() } : null;
return [{ json: { ...cfg, channelKey: 'localStackAi', channelName: cfg.channelName || 'Local Stack AI', workflowPackVersion: cfg.workflowPackVersion || 'v24', requestedRunType, runType: requestedRunType, sharedContentWorkflowId, sharedAnalyticsWorkflowId, sharedStrategyWorkflowId, missingFieldNames, missingBindings, setupReady, status, reason, targetWorkflowId, setupAudit: requestedRunType === 'SETUP_AUDIT', runLockKey, deadLetter } }];

const payload = $input.first().json || {};
const riskFlags = Array.isArray(payload.riskFlags) ? payload.riskFlags : [];
const publishBlockedByRisk = riskFlags.length > 0;
let status = payload.status || 'WRAPPER_COMPLETE';
let reason = payload.reason || '';
if (publishBlockedByRisk) { status = 'PUBLISH_BLOCKED_RISK'; reason = 'Risk flags detected; publish path disabled'; }
const slackWebhook = payload.slackWebhook || '';
const isWin = payload.status === 'ANALYTICS_COMPLETE' && payload.metrics && parseFloat(String(payload.metrics.subsPerDay || '0')) >= (payload.velocityTargets?.subsPerDayTarget || 10);
const slackMessage = isWin && slackWebhook && !slackWebhook.startsWith('https://hooks.slack.com/services/T00000')
  ? 'WIN: ' + (payload.channelName || 'Local Stack AI') + ' hit ' + payload.metrics.subsPerDay + ' subs/day (' + payload.analyticsWindow + '). Offer CVR: ' + payload.metrics.offerCvr + '%. Top action: ' + (payload.aiInterpretation?.topAction || 'N/A')
  : null;
return [{ json: { ...payload, status, reason, publishBlockedByRisk, publishEligible: !publishBlockedByRisk && payload.publishReady !== false, isWin, slackMessage, deadLetter: publishBlockedByRisk ? { channelKey: 'localStackAi', channelName: payload.channelName || 'Local Stack AI', runType: payload.runType, reason, riskFlags, at: new Date().toISOString() } : (payload.deadLetter || null) } }];
